INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('sunshine-golf', 'Sunshine Golf Classic', 'Sunshine Golf Classic', 'sunshine golf classic yangguang gaoerfu js13k frank force killedbyapixel golf13k', 'Frank Force (KilledByAPixel)', '', '', NULL, '', 0, 2026, 'action', '["体育","高尔夫"]', 140, 0.12, 'io', 'https://killedbyapixel.github.io/Golf13K/', 0, 0, 0, 1, 0, 0, 1, 'mid', 'hosted', '在晴朗的球场上挥杆，把球打上果岭', '一款轻松的三维高尔夫：看风向、选杆、把球打上果岭，打完程序生成的十八洞。', 'A relaxed 3D golf game: read the wind, pick a club, land the ball on the green, and play through a procedurally generated 18-hole course.', '由 Frank Force（KilledByAPixel）制作，2026 年参加 JS13K 并在 killedbyapixel.github.io/Golf13K 公开发布。原页托管在 killedbyapixel.github.io/Golf13K，不是即玩的作品。在即玩里直接打开原作。开玩不用登录。', 'Made by Frank Force (KilledByAPixel) for JS13K 2026 and published at killedbyapixel.github.io/Golf13K. Hosted at killedbyapixel.github.io/Golf13K; it is not a Jiwan original. It opens here. No account needed.', 'assets/posters/sunshine-golf.jpg', 1280, 800, 'center', '["assets/posters/sunshine-golf.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -54, 1795572000000, 'Swing on a sunny course and try to land the ball on the green.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('sp13ktra', 'SP13KTRA', 'SP13KTRA', 'sp13ktra spectra jingisu fanshouli jingsu js13k frank force killedbyapixel', 'Frank Force (KilledByAPixel)', '', '', NULL, '', 0, 2026, 'action', '["竞速","动作"]', 10, 0.16, 'io', 'https://killedbyapixel.github.io/SP13KTRA/', 0, 0, 0, 1, 0, 0, 1, 'mid', 'hosted', '在彩虹色的赛道上飞起来，跟八名车手比谁更快', '一款反重力竞速：八条赛道、八名车手，用键盘或鼠标驾驶，把每条赛道的最好成绩留下来。', 'An anti-gravity racer: eight circuits and eight racers, steer with the keyboard or the mouse, and keep your best time on every track.', '由 Frank Force（KilledByAPixel）制作，2026 年参加 JS13K 并在 killedbyapixel.github.io/SP13KTRA 公开发布。原页托管在 killedbyapixel.github.io/SP13KTRA，不是即玩的作品。在即玩里直接打开原作。开玩不用登录。', 'Made by Frank Force (KilledByAPixel) for JS13K 2026 and published at killedbyapixel.github.io/SP13KTRA. Hosted at killedbyapixel.github.io/SP13KTRA; it is not a Jiwan original. It opens here. No account needed.', 'assets/posters/sp13ktra.jpg', 1280, 800, 'center', '["assets/posters/sp13ktra.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -55, 1795572000000, 'Race the rainbow circuits and see if you can beat the other seven.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('cat-survivors', 'Cat Survivors', 'Cat Survivors', 'cat survivors maomi xingcunzhe shengcun paoku js13k ilya kuzmichev alexandra alhovik eliasku', 'Ilya Kuzmichev, Alexandra Alhovik', '', '', NULL, '', 0, 2025, 'action', '["动作","生存"]', 80, 0.12, 'io', 'https://cat-survivors.netlify.app/', 0, 0, 0, 1, 0, 0, 1, 'mid', 'hosted', '操控一只小猫，在战场上尽量活过十分钟', '一款幸存者动作游戏：操控小猫四处游走、升级和收集，尽量在战场上活过十分钟。', 'A survivor-style action game: steer a cat, level up and collect loot, and try to last ten minutes on the battlefield.', '由 Ilya Kuzmichev 与 Alexandra Alhovik 制作，2025 年参加 JS13K，导演剪辑版在 cat-survivors.netlify.app 公开发布。原页托管在 cat-survivors.netlify.app，不是即玩的作品。在即玩里直接打开原作。开玩不用登录。', 'Made by Ilya Kuzmichev and Alexandra Alhovik for JS13K 2025; this is the director''s cut published at cat-survivors.netlify.app. Hosted at cat-survivors.netlify.app; it is not a Jiwan original. It opens here. No account needed.', 'assets/posters/cat-survivors.jpg', 1280, 800, 'center', '["assets/posters/cat-survivors.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -56, 1795572000000, 'Play as a cat and try to survive ten minutes on the battlefield.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('tatham-untangle', 'Untangle', 'Untangle', 'untangle jiekai jiesheng tuodiantou simon tatham portable puzzle collection', 'Simon Tatham', '', '', NULL, '', 0, 2005, 'puzzle', '["益智","解谜"]', 210, 0.04, 'story', 'https://www.chiark.greenend.org.uk/~sgtatham/puzzles/js/untangle.html', 0, 0, 0, 1, 0, 0, 1, 'short', 'hosted', '把缠在一起的点拉开，让连线互不相交', '一款益智解谜：拖动各个点的位置，让所有连线不再交叉。', 'A logic puzzle: drag the points around until none of the lines cross.', '由 Simon Tatham 制作，是 Portable Puzzle Collection 中的一款，2005 年起在 chiark.greenend.org.uk 公开发布，源码以 MIT 许可发布。原页托管在 chiark.greenend.org.uk，不是即玩的作品。在即玩里直接打开原作。开玩不用登录。', 'Made by Simon Tatham as part of his Portable Puzzle Collection, published at chiark.greenend.org.uk since 2005, and released under the MIT License. Hosted at chiark.greenend.org.uk; it is not a Jiwan original. It opens here. No account needed.', 'assets/posters/tatham-untangle.jpg', 1280, 800, 'center', '["assets/posters/tatham-untangle.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -57, 1795572000000, 'Drag the points apart so that none of the lines cross.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('spacepi', 'SpacePi', 'SpacePi', 'spacepi space pi taikong jidi shubiao fanying js13k jack rugile', 'Jack Rugile', '', '', NULL, '', 0, 2012, 'action', '["动作","射击"]', 180, 0.08, 'io', 'https://jackrugile.com/spacepi/', 0, 0, 0, 1, 0, 0, 1, 'short', 'hosted', '守住太空里的十三座基地，别让它们被打掉', '一款鼠标反应游戏：在最荒凉的太空里保护十三座基地，看你能守多久。', 'A mouse-accuracy game: defend 13 bases in the most desolate regions of space and see how long you can hold out.', '由 Jack Rugile 制作，2012 年参加 JS13K 并在 jackrugile.com/spacepi 公开发布，源码以 MIT 许可发布。原页托管在 jackrugile.com/spacepi，不是即玩的作品。在即玩里直接打开原作。开玩不用登录。', 'Made by Jack Rugile for JS13K 2012, published at jackrugile.com/spacepi, and released under the MIT License. Hosted at jackrugile.com/spacepi; it is not a Jiwan original. It opens here. No account needed.', 'assets/posters/spacepi.jpg', 1280, 800, 'center', '["assets/posters/spacepi.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -58, 1795572000000, 'Defend thirteen bases in deep space and keep them from being destroyed.', '', '', 1);
